patch:
diff --git a/repro-18575.cjs b/repro-18575.cjs
new file mode 100644
index 0000000..f46e290
--- /dev/null
+++ b/repro-18575.cjs
@@ -0,0 +1,67 @@
+/**
+ * Reproduction for "files on a different drive are not ignored on Windows".
+ *
+ * Simulates win32 path semantics on a non-Windows host: every userland
+ * `require("path")` / `require("node:path")` (ESLint, @eslint/config-array,
+ * etc.) receives `path.win32`. Node's own loader is unaffected.
+ *
+ * Run: node repro-18575.cjs
+ */
+"use strict";
+
+const Module = require("node:module");
+const realPath = require("node:path");
+
+if (process.platform !== "win32") {
+    const originalLoad = Module._load;
+
+    Module._load = function(request, ...rest) {
+        if (request === "path" || request === "node:path") {
+            return realPath.win32;
+        }
+        return originalLoad.call(this, request, ...rest);
+    };
+}
+
+const { ESLint, Linter } = require("./lib/api");
+
+const CWD = "C:\\Project";
+const cases = [
+    { file: "C:\\Project\\foo.js", expectIgnored: false, note: "inside cwd" },
+    { file: "C:\\Other\\foo.js", expectIgnored: true, note: "outside cwd, same drive" },
+    { file: "F:\\foo.js", expectIgnored: true, note: "outside cwd, different drive (reported)" }
+];
+
+(async () => {
+    console.log(`simulated win32: ${process.platform !== "win32"}, cwd: ${CWD}`);
+    console.log(`path.win32.relative(${JSON.stringify(CWD)}, "F:\\\\foo.js") = ${JSON.stringify(realPath.win32.relative(CWD, "F:\\foo.js"))}\n`);
+
+    const eslint = new ESLint({
+        cwd: CWD,
+        overrideConfigFile: true,
+        overrideConfig: { rules: { "no-undef": "error" } }
+    });
+    const linter = new Linter({ configType: "flat", cwd: CWD });
+    let failures = 0;
+
+    for (const { file, expectIgnored, note } of cases) {
+        const ignored = await eslint.isPathIgnored(file);
+        const [result] = await eslint.lintText("foo();", { filePath: file, warnIgnored: true });
+        const lintMessages = result.messages.map(m => m.message).join(" | ");
+        const linterMessages = linter.verify("foo()", { rules: { "no-undef": "error" } }, file)
+            .map(m => m.message).join(" | ");
+        const ok = ignored === expectIgnored;
+
+        if (!ok) {
+            failures++;
+        }
+
+        console.log(`${ok ? "OK  " : "BUG "} ${file}  (${note})`);
+        console.log(`     expected ignored=${expectIgnored}, ESLint#isPathIgnored=${ignored}`);
+        console.log(`     ESLint#lintText: ${lintMessages || "(no messages)"}`);
+        console.log(`     Linter#verify:   ${linterMessages || "(no messages)"}\n`);
+    }
+
+    console.log(failures ? `${failures} case(s) show the bug` : "no bug observed");
+    process.exitCode = failures ? 1 : 0;
+})();
